import json, collections, numpy as np
l=load_lab()
pairs=[]
g=collections.defaultdict(list)
for r in l:
 if r['family'] in ['multivariate_regression','univariate_regression'] and not r.get('excluded') and np.isfinite(r['mean']):
  g[(r['set_id'],json.dumps(r['model'],sort_keys=True),json.dumps(r['loss'],sort_keys=True))].append(r)
for rows in g.values():
 for s in rows:
  if s['optimizer']['type'].lower()!='sgd' or s['optimizer'].get('momentum',0)!=0: continue
  for a in rows:
   if a['optimizer']['type'].lower() not in ['adam','adamw']: continue
   ratio=s['optimizer']['lr']*.01/a['optimizer']['lr']
   if .5<=ratio<=2:
    pairs.append((s,a,ratio))
print('parity pairs',len(pairs))
for fam in ['multivariate_regression','univariate_regression']:
 for scope in ['all','rectifier','deepLN','long','focal']:
  pp=[p for p in pairs if p[0]['family']==fam and (scope=='all' or scope=='rectifier' and p[0]['activation'] in ['relu','leaky_relu'] or scope=='deepLN' and p[0]['depth']>=3 and p[0]['n_ln']>=1 or scope=='long' and p[0]['budget']['training_steps']>=1024 or scope=='focal' and p[0]['activation'] in ['relu','leaky_relu'] and p[0]['depth']>=3 and p[0]['n_ln']>=1 and p[0]['budget']['training_steps']>=1024)]
  print(fam,scope,len(pp),sum(s['mean']<a['mean'] for s,a,_ in pp),'sets',len(set(s['set_id'] for s,a,_ in pp)), 'median',np.median([s['mean']/a['mean'] for s,a,_ in pp]) if pp else None)
print('mvar examples')
for s,a,r in pairs:
 if s['family']=='multivariate_regression':
  print(s['dataset_id'],s['budget']['training_steps'],s['depth'],s['activation'],s['n_ln'],s['optimizer'],a['optimizer'],round(s['mean']/a['mean'],3))
